#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/commands/gallery_command/gallery_command.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// RibbonGallery's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/ribbon_gallery.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The value command whose value the selection follows, which a click or Enter commits and which receives previews, or null. Without one the gallery keeps its own selection and offers no preview.
template <typename Declaring>
struct RibbonGalleryCommandCapability {
    PropertyCell<std::shared_ptr<GalleryCommand>, RibbonGalleryCommandCapability<Declaring>> command{};

    static void assign(RibbonGalleryCommandCapability& capability, std::shared_ptr<GalleryCommand> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.command), incoming);
        if (!capability.command.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.command));
    }
};

// Every item's image area, in logical units at text scale 1. A size outside 16 to 256 on either side throws std::out_of_range.
template <typename Declaring>
struct RibbonGalleryItemSizeCapability {
    PropertyCell<Size, RibbonGalleryItemSizeCapability<Declaring>> item_size{Size{48.0, 48.0}};

    static void assign(RibbonGalleryItemSizeCapability& capability, Size incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.item_size), incoming);
        if (!capability.item_size.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.item_size));
    }
};

// Whether labels show under the images.
template <typename Declaring>
struct RibbonGalleryShowLabelsCapability {
    PropertyCell<bool, RibbonGalleryShowLabelsCapability<Declaring>> show_labels{};

    static void assign(RibbonGalleryShowLabelsCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_labels), incoming);
        if (!capability.show_labels.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_labels));
    }
};

// In-ribbon form: the rows shown (1 to 8). A count outside that throws std::out_of_range.
template <typename Declaring>
struct RibbonGalleryVisibleRowsCapability {
    PropertyCell<std::size_t, RibbonGalleryVisibleRowsCapability<Declaring>> visible_rows{3U};

    static void assign(RibbonGalleryVisibleRowsCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.visible_rows), incoming);
        if (!capability.visible_rows.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.visible_rows));
    }
};

// In-ribbon form: the current column count, kept inside the column range (owner decision RB-8: the ribbon's scaling gives up one column at a time within it). A count outside the range throws std::out_of_range.
template <typename Declaring>
struct RibbonGalleryColumnsCapability {
    PropertyView<std::size_t, RibbonGalleryColumnsCapability<Declaring>> columns;

    static void assign(RibbonGalleryColumnsCapability& capability, std::size_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.columns), std::move(incoming));
    }

    static std::size_t read(const RibbonGalleryColumnsCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::size_t current = control.read_view(capability.columns);
        return current;
    }
};

// The selected item's ID: the command's value, or the gallery's own selection; a write selects without committing (the command's set_value) and throws std::invalid_argument for an ID the gallery does not have. A view onto the command or the gallery's own selection.
template <typename Declaring>
struct RibbonGallerySelectedIdCapability {
    PropertyView<std::optional<std::string>, RibbonGallerySelectedIdCapability<Declaring>> selected_id;

    static void assign(RibbonGallerySelectedIdCapability& capability, std::optional<std::string> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_id), std::move(incoming));
    }

    static std::optional<std::string> read(const RibbonGallerySelectedIdCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::optional<std::string> current = control.read_view(capability.selected_id);
        return current;
    }
};

// Every RibbonGallery capability, in the order the declaring class takes them.
template <typename Declaring>
struct RibbonGalleryCapabilities : public RibbonGalleryCommandCapability<Declaring>,
                                   public RibbonGalleryItemSizeCapability<Declaring>,
                                   public RibbonGalleryShowLabelsCapability<Declaring>,
                                   public RibbonGalleryVisibleRowsCapability<Declaring>,
                                   public RibbonGalleryColumnsCapability<Declaring>,
                                   public RibbonGallerySelectedIdCapability<Declaring> {};

} // namespace gui_forms
